import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp,rm,readFile,readdir} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {OpenAiAssistant,openaiFunctions} from '../daemon/bootstrap/agent/openai-assistant.mjs';
import {ProjectStore} from '../daemon/bootstrap/project-store.mjs';
import {SceneWorkspace} from '../daemon/bootstrap/scene-workspace.mjs';
import {ProposalManager} from '../daemon/bootstrap/workspaces/manager.mjs';
import {CommandBus} from '../daemon/bootstrap/command-bus.mjs';
import {AgentService} from '../daemon/bootstrap/agent/service.mjs';
import {EditorBridge} from '../daemon/bootstrap/agent/editor-bridge.mjs';
import {newPmd,updatePmd,advancePmd} from '../engine/project/pmd.mjs';
const message=text=>({type:'message',role:'assistant',content:[{type:'output_text',text}]}),response=output=>({status:'completed',output,usage:{input_tokens:30,output_tokens:20,total_tokens:50}}),tool=(name,args,id)=>({type:'function_call',name:'axiom_tool',call_id:id,arguments:JSON.stringify({name,arguments:JSON.stringify(args)})});
test('Platform P3: limits configured before choosing a model survive restart without connecting or generation',async t=>{
 const root=await mkdtemp(join(tmpdir(),'axiom-p3-no-model-')),workspace=new SceneWorkspace(new ProjectStore(root));await workspace.run('project.create',{name:'No model selected'});
 const proposals=new ProposalManager(workspace);await proposals.initialize();const bus=new CommandBus({projects:workspace}),bridge=new EditorBridge(workspace,()=>{});
 const options={workspace,proposals,bus,bridge,apiKey:'',fetchImpl:async()=>{throw Error('No provider call is authorized by changing local limits');}};
 const first=new OpenAiAssistant(options);await first.ready;await first.configure({action:'update',limits:{maxRequests:3}});await first.close();
 const next=new OpenAiAssistant(options);await next.ready;t.after(async()=>{await next.close();bridge.close();await proposals.close();await rm(root,{recursive:true,force:true});});
 assert.equal(next.status().model,'');assert.equal(next.status().connected,false);assert.equal(next.status().hasCredential,false);assert.equal(next.status().limits.maxRequests,3);assert.equal(next.status().sessionUsage.totalTokens,0);
});
function transport(outputs){const requests=[];return {requests,fetch:async(url,options)=>{requests.push({url,...options,body:options.body?JSON.parse(options.body):null});return new Response(JSON.stringify(url.endsWith('/models')?{data:[{id:'gpt-4.1'}]}:response(outputs.shift()??[message('OK')])),{status:200});}};}
async function fixture(t,outputs=[],options={}){const root=await mkdtemp(join(tmpdir(),'axiom-ai-')),workspace=new SceneWorkspace(new ProjectStore(root));await workspace.run('project.create',{name:'AI Lab'});await workspace.run('scene.entity.create',{id:workspace.project.id,expectedSceneRevision:workspace.revision,name:'Cube'});await workspace.run('scene.save',{id:workspace.project.id,expectedSceneRevision:workspace.revision});const proposals=new ProposalManager(workspace);await proposals.initialize();const bus=new CommandBus({projects:workspace}),bridge=new EditorBridge(workspace,()=>{});bus.agentService=new AgentService({workspace,bus,bridge});bus.agentService.proposals=proposals;const http=transport([[message('OK')],...outputs]),ai=new OpenAiAssistant({bus,workspace,proposals,bridge,apiKey:'',fetchImpl:http.fetch,capabilityProbe:async()=>({compiler:true}),...options});bus.agentService.assistant=ai;
 // Existing workflow fixtures exercise execution with a pre-approved task plan.
 // Dedicated confirmation tests below exercise the default human approval gate.
 if(!options.testConfirmation){const start=ai.start.bind(ai);ai.start=data=>{const task=start({...data,requireConfirmation:false});const order=ai.sessions.get(task.id);order.taskPlan=['Execute the explicitly scoped test scenario and verify its assertions'];order.approvalGranted=true;return task;};}
 t.after(async()=>{await ai.close();bridge.close();await proposals.close();await rm(root,{recursive:true,force:true});});await ai.configure({action:'connect',apiKey:'sk-test-supersecret',model:'gpt-4.1'});return {ai,workspace,proposals,bridge,root,http};}
async function complete(ai,data){const started=ai.start(data);await ai.sessions.get(started.id).flight;return ai.task(started.id);}
test('GitHub publication tools pin saved MAIN without creating an authoring proposal',async t=>{const {ai,workspace,proposals}=await fixture(t,[[tool('github.preview',{},'preview')],[tool('github.publish',{planId:'reviewed-plan'},'publish')],[message('Saved MAIN publication confirmed.')]]);const calls=[];ai.bus.agentService.github={prepare:async data=>{calls.push(data);return {planId:'reviewed-plan'};},publish:async(data,context)=>{calls.push({data,actor:context.actor});return {lastPublication:{sha:'abc'}};}};const task=await complete(ai,{text:'Publish the saved game project through the GitHub preference already enabled.'});assert.equal(task.status,'completed');assert.equal(proposals.items.size,0);assert.equal(calls[0].id,workspace.project.id);assert.equal(calls[0].expectedSceneRevision,workspace.revision);assert.equal(calls[1].actor.kind,'agent');assert.equal(calls[1].data.planId,'reviewed-plan');});
test('semantic stop retains the successful mutation receipt and actual outcome before stopping unrelated edits',async t=>{
 const {ai,workspace,proposals}=await fixture(t);const created=await proposals.run('workspace.begin',{id:workspace.project.id,expectedSceneRevision:workspace.revision},{}),child=proposals.get(created.id).child;
 const extra=await child.run('scene.entity.create',{id:child.project.id,expectedSceneRevision:child.revision,name:'Unrelated'}),id=extra.project.scene.entities.at(-1).id;
 const s={public:{id:'receipt-test',workspaceId:created.id,channel:'assistant',originalObjective:'Move Cube'},plan:{mode:'authoring',steps:[{id:'move',status:'todo',checks:[{kind:'entity',selector:'Cube',property:'transform.position.0',expected:2}]}]},receipts:[],resources:{}};const persisted=[];
 ai.checkpoint=async value=>persisted.push(structuredClone(value.receipts));ai.callTool=async(_s,call)=>{const args=JSON.parse(JSON.parse(call.arguments).arguments);await child.run('scene.entity.update',{id:child.project.id,expectedSceneRevision:child.revision,...args});return {committedName:args.name};};
 for(let n=0;n<16;n++)await ai.performCall(s,tool('scene.entity.update',{entityId:id,name:'Unrelated '+n},'edit-'+n));
 await assert.rejects(ai.performCall(s,tool('scene.entity.update',{entityId:id,name:'Unrelated 16'},'edit-16')),error=>error.code==='AX_AI_NO_PROGRESS'&&error.operationResult.committedName==='Unrelated 16');
 assert.equal(child.project.scene.entities.find(e=>e.id===id).name,'Unrelated 16');assert.equal(s.receipts.length,17);assert.equal(persisted.at(-1).length,17);assert.equal(s.pendingOperation,null);assert.equal(workspace.project.scene.entities.length,1);
});
test('connection test/model discovery are explicit; credentials never enter status or projects',async t=>{const {ai,workspace,http,root}=await fixture(t);assert.equal(ai.status().connected,true);assert.deepEqual(await ai.configure({action:'models'}),{models:['gpt-4.1'],untestedModels:[]});assert.equal(http.requests[0].url,'https://api.openai.com/v1/responses');assert.equal(http.requests[0].body.store,false);assert.deepEqual(http.requests[0].body.tools,openaiFunctions);assert.equal(http.requests[0].headers.Authorization,'Bearer sk-test-supersecret');assert.ok(!JSON.stringify(ai.status()).includes('supersecret'));assert.ok(!(await readFile(join(root,workspace.store.filename(workspace.project.id)),'utf8')).includes('supersecret'));await ai.configure({action:'disconnect'});assert.equal(ai.status().hasCredential,false);assert.throws(()=>ai.start({text:'Hello'}),/Connect/);});
test('sequential reasoning/tool turns edit isolated proposal and return real outcomes',async t=>{const {ai,workspace,proposals,http,root}=await fixture(t);const original=structuredClone(workspace.snapshot()),disk=await readFile(join(root,workspace.store.filename(workspace.project.id))),entity=workspace.project.scene.entities[0];const reasoning={type:'reasoning',id:'reason-1',summary:[]};http.fetch;const outputs=[[reasoning,tool('entity.query',{},'query')],[tool('scene.entity.update',{entityId:entity.id,transform:{position:[2,0,0]}},'move')],[tool('entity.query',{entityId:entity.id},'verify')],[message('Moved Cube to X=2 in a proposal; verified its position.')]];ai.fetchImpl=async(url,opts)=>{http.requests.push({url,body:JSON.parse(opts.body)});return new Response(JSON.stringify(response(outputs.shift())),{status:200});};const task=await complete(ai,{text:'Move Cube to X=2 and verify.'});assert.equal(task.status,'completed');assert.equal(task.requests,4);assert.equal(task.toolCalls,3);assert.equal(task.usage.totalTokens,200);assert.deepEqual(workspace.snapshot(),original);assert.deepEqual(await readFile(join(root,workspace.store.filename(workspace.project.id))),disk);assert.equal(proposals.get(task.workspaceId).child.project.scene.entities[0].transform.position[0],2);assert.ok(http.requests.at(-1).body.input.some(i=>i.id==='reason-1'));assert.ok(!JSON.stringify(task).includes('reason-1'));assert.ok(http.requests.at(-1).body.input.some(i=>i.type==='function_call_output'&&JSON.parse(i.output).items?.[0]?.transform.position[0]===2));});
test('readonly chat works on dirty MAIN without generating a proposal',async t=>{const {ai,workspace,proposals}=await fixture(t,[[tool('entity.query',{},'read')],[message('One cube.')]]);await workspace.run('scene.entity.update',{id:workspace.project.id,expectedSceneRevision:workspace.revision,entityId:workspace.project.scene.entities[0].id,name:'Edited'});const task=await complete(ai,{text:'What is in the scene?'});assert.equal(task.status,'completed');assert.equal(task.workspaceId,null);assert.equal(proposals.items.size,0);});
test('forbidden save/accept/project scope calls become tool errors; assistant can recover',async t=>{const {ai,workspace,proposals,http}=await fixture(t,[[tool('scene.save',{},'save')],[tool('entity.query',{id:'project://other'},'escape')],[tool('workspace.accept',{},'accept')],[message('These operations are unavailable.')]]);const task=await complete(ai,{text:'Test capability boundaries.'});assert.equal(task.status,'completed');assert.deepEqual(task.steps.map(s=>s.status),['failed','failed','failed']);assert.equal(proposals.items.size,0);assert.equal(workspace.dirty,false);assert.ok(http.requests.at(-1).body.input.filter(i=>i.type==='function_call_output').every(i=>JSON.parse(i.output).error));});
test('request/tool/token budgets stop work without applying partial proposals',async t=>{const {ai,workspace,proposals}=await fixture(t);await ai.configure({action:'update',limits:{maxTools:1}});ai.fetchImpl=async()=>new Response(JSON.stringify(response([tool('scene.entity.update',{entityId:workspace.project.scene.entities[0].id,name:'Proposed'},randomId())])),{status:200});function randomId(){return String(Math.random());}const task=await complete(ai,{text:'Repeat changes.'});assert.equal(task.status,'failed');assert.match(task.error.message,/tool-call budget/);assert.equal(workspace.project.scene.entities[0].name,'Cube');assert.equal(proposals.get(task.workspaceId).child.project.scene.entities[0].name,'Proposed');await ai.configure({action:'update',limits:{maxTokens:4096}});ai.fetchImpl=async()=>new Response(JSON.stringify({...response([tool('runtime.status',{},'over-cap')]),usage:{total_tokens:5000}}));const limited=await complete(ai,{text:'Do work.'});assert.equal(limited.status,'failed');assert.match(limited.error.message,/token budget/);});
test('failed credential/remote error never exposes provider body or secrets',async t=>{const {ai}=await fixture(t);ai.fetchImpl=async()=>new Response(JSON.stringify({error:{message:'sk-new-key-secret'}}),{status:401});await assert.rejects(ai.configure({action:'connect',apiKey:'sk-new-key-secret',model:'gpt-4.1'}),e=>!e.message.includes('secret')&&e.message.includes('401'));assert.equal(ai.status().connected,false);ai.fetchImpl=async()=>new Response('x'.repeat(2*1024*1024+1));await assert.rejects(ai.configure({action:'models'}),/transport budget/);});
