test('assistant can continue the same pending proposal without mutating MAIN',async t=>{const {ai,workspace,proposals}=await fixture(t);const entity=workspace.project.scene.entities[0];let turns=[[tool('scene.entity.update',{entityId:entity.id,name:'First'},'1')],[message('First change.')]];ai.fetchImpl=async()=>new Response(JSON.stringify(response(turns.shift())),{status:200});const first=await complete(ai,{text:'First change'});turns=[[tool('scene.entity.update',{entityId:entity.id,name:'Second'},'2')],[message('Second change.')]];const second=await complete(ai,{text:'Improve it',workspaceId:first.workspaceId});assert.equal(second.status,'completed');assert.equal(second.workspaceId,first.workspaceId);assert.equal(proposals.get(first.workspaceId).child.project.scene.entities[0].name,'Second');assert.equal(entity.name,'Cube');assert.equal(workspace.project.scene.entities[0].name,'Cube');assert.equal(proposals.items.size,1);});
