test('incomplete responses and invalid schemas cannot turn into successful mutations',async t=>{const {ai,workspace,proposals}=await fixture(t,[[tool('scene.entity.update',{entityId:workspacePlaceholder(),transform:{position:[1,2]}},'invalid')],[message('The schema rejected the edit.')]]);function workspacePlaceholder(){return 'entity://00000000-0000-4000-8000-000000000000';}const before=structuredClone(workspace.snapshot()),task=await complete(ai,{text:'Try invalid transform'});assert.equal(task.steps[0].status,'failed');assert.deepEqual(workspace.snapshot(),before);assert.equal(proposals.items.size,1);ai.fetchImpl=async()=>new Response(JSON.stringify({status:'incomplete',output:[message('Should not be accepted')],usage:{total_tokens:50}}));const failed=await complete(ai,{text:'Try incomplete'});assert.equal(failed.status,'failed');assert.match(failed.error.message,/did not complete/);});
test('transport timeout signal and credential redaction protect task histories',async t=>{const {ai,http}=await fixture(t,[[message('sk-test-supersecret')]]);const task=await complete(ai,{text:'Never transmit sk-test-supersecret in project context.'});assert.ok(!JSON.stringify(task).includes('supersecret'));assert.ok(!JSON.stringify(http.requests.at(-1).body).includes('supersecret'));assert.equal(task.messages[0],'[redacted]');ai.connected=false;ai.fetchImpl=async()=>{throw Error('Private provider error sk-test-supersecret');};await assert.rejects(ai.configure({action:'connect',model:'gpt-4.1'}),e=>!e.message.includes('secret')&&/unreachable/.test(e.message));});

test('continued task context includes proposal-created files and entities, not the original branch',async t=>{const {ai,workspace,proposals}=await fixture(t);const proposal=await proposals.run('workspace.begin',{id:workspace.project.id,expectedSceneRevision:workspace.revision},{actor:{kind:'agent'}});const p=proposals.get(proposal.id);await proposals.execute('scene.entity.create',{id:workspace.project.id,workspaceId:p.id,expectedSceneRevision:p.child.revision,name:'Only in proposal'},{actor:{kind:'agent'}});await proposals.execute('project.files.edit',{id:workspace.project.id,workspaceId:p.id,expectedSceneRevision:p.child.revision,action:'create',kind:'script',path:'Scripts/ProposalOnly.cs'},{actor:{kind:'agent'}});const context=ai.context({public:{workspaceId:p.id}});assert.ok(context.entities.some(e=>e.name==='Only in proposal'));assert.ok(context.files.some(f=>f.path==='Scripts/ProposalOnly.cs'));assert.equal(workspace.project.scene.entities.length,1);});
test('discovery bootstraps without circular schema guessing and can proceed to an isolated edit',async t=>{const {ai,workspace,http,proposals}=await fixture(t);const entity=workspace.project.scene.entities[0];let outputs=[[tool('api.describe',{name:'entity.query'},'describe-query')],[tool('api.describe',{kind:'tool',name:'scene.entity.update'},'describe-update')],[tool('entity.query',{name:'Cube'},'read')],[tool('scene.entity.update',{entityId:entity.id,transform:{position:[2,0,0]}},'edit')],[tool('entity.query',{entityId:entity.id},'verify')],[message('Verified proposal X=2.')]];ai.fetchImpl=async(url,options)=>{http.requests.push({url,body:JSON.parse(options.body)});return new Response(JSON.stringify(response(outputs.shift())));};const task=await complete(ai,{text:'Inspect and move Cube.'});assert.equal(task.status,'completed');assert.equal(task.requests,6);assert.ok(task.steps.every(s=>s.status==='completed'));assert.equal(entity.transform.position[0],0);assert.equal(proposals.get(task.workspaceId).child.project.scene.entities[0].transform.position[0],2);assert.match(http.requests.at(-1).body.instructions,/Real schemas are supplied/);assert.ok(http.requests.at(-1).body.input.some(i=>i.type==='function_call_output'&&JSON.parse(i.output).name==='entity.query'));});
test('invalid discovery arguments return the precise contract instead of five blind retries',async t=>{const {ai,http}=await fixture(t,[[tool('api.describe',{tool:'entity.query'},'bad')],[tool('api.describe',{kind:'tool',name:'entity.query'},'correct')],[message('Discovery recovered.')]]);const task=await complete(ai,{text:'Discover entity.query.'});assert.deepEqual(task.steps.map(s=>s.status),['failed','completed']);const feedback=http.requests.at(-1).body.input.filter(i=>i.type==='function_call_output').map(i=>JSON.parse(i.output)).find(i=>i.error);assert.deepEqual(feedback.inputSchema.required,['kind','name']);});
test('model listing excludes incompatible models but retains untested models without generation',async t=>{const {ai}=await fixture(t);const calls=[];ai.fetchImpl=async(url)=>{calls.push(url);return new Response(JSON.stringify({data:['whisper-1','gpt-4o-audio-preview','gpt-image-1','text-embedding-3-large','gpt-4.1','gpt-4.1-2025-04-14','gpt-6.1-sol','gpt-6.1-sol-realtime','future-model','ft:gpt-4.1:org:id'].map(id=>({id}))}));};assert.deepEqual((await ai.configure({action:'models'})).models,['ft:gpt-4.1:org:id','future-model','gpt-4.1','gpt-4.1-2025-04-14','gpt-6.1-sol','gpt-6.1-sol-realtime']);assert.deepEqual(calls,['https://api.openai.com/v1/models']);await assert.rejects(ai.configure({action:'connect',model:'whisper-1'}),/incompatible/);assert.equal(calls.length,1);});

test('session uses reported totals, accepts one million and persists limits/usage across disconnect and daemon recreation',async t=>{const {ai,workspace,proposals,root}=await fixture(t);await ai.configure({action:'update',limits:{maxTokens:10000}});ai.fetchImpl=async()=>new Response(JSON.stringify({...response([tool('entity.query',{},'pending')]),usage:{input_tokens:10900,output_tokens:50,total_tokens:10950}}));const task=await complete(ai,{text:'Inspect the unfinished task'});assert.equal(task.status,'failed');assert.equal(task.canResume,true);assert.equal(ai.status().sessionUsage.totalTokens,11000);assert.equal(ai.status().remainingTokens,0);assert.equal(task.toolCalls,0);assert.throws(()=>ai.start({text:'Continue before increasing limit'}),/session token budget/);assert.equal(ai.status().lastTaskId,task.id);await ai.configure({action:'update',limits:{maxTokens:20000}});assert.equal(ai.status().remainingTokens,9000);await ai.configure({action:'disconnect'});assert.equal(ai.status().sessionUsage.totalTokens,11000);const restored=new OpenAiAssistant({bus:ai.bus,workspace,proposals,bridge:ai.bridge,apiKey:''});await restored.ready;assert.equal(restored.status().limits.maxTokens,20000);assert.equal(restored.status().sessionUsage.totalTokens,11000);assert.equal(restored.status().remainingTokens,9000);assert.equal(restored.status().connected,false);await restored.configure({action:'update',limits:{maxTokens:1000000}});assert.equal(restored.status().remainingTokens,989000);const file=await readFile(join(root,'.assistant-session.json'),'utf8');assert.ok(!file.includes('supersecret'));assert.ok(!file.includes('Inspect the unfinished task'));});
test('raised session budget resumes pending tool calls/objective exactly once, without resetting usage or modifying MAIN',async t=>{const {ai,workspace,proposals,http}=await fixture(t);const entity=workspace.project.scene.entities[0];await ai.configure({action:'update',limits:{maxTokens:10000}});let round=0;ai.fetchImpl=async(url,options)=>{const body=JSON.parse(options.body);http.requests.push({url,body});round++;const output=round===1?[tool('scene.entity.update',{entityId:entity.id,transform:{position:[2,0,0]}},'resume-edit')]:[message('Verified the resumed edit.')];return new Response(JSON.stringify({...response(output),usage:{total_tokens:round===1?10950:50}}));};const first=await complete(ai,{text:'Move Cube to X=2'});assert.equal(first.canResume,true);assert.equal(proposals.items.size,0);await ai.configure({action:'update',limits:{maxTokens:20000}});const next=await complete(ai,{text:'Continue your unfinished task',resumeTaskId:first.id});assert.equal(next.status,'completed');assert.equal(next.resumedFrom,first.id);assert.equal(next.originalObjective,'Move Cube to X=2');assert.equal(next.steps.length,1);assert.equal(next.steps[0].tool,'scene.entity.update');assert.equal(proposals.get(next.workspaceId).child.project.scene.entities[0].transform.position[0],2);assert.equal(entity.transform.position[0],0);assert.equal(ai.status().sessionUsage.totalTokens,11050);assert.ok(http.requests.at(-1).body.input.some(i=>i.role==='developer'&&i.content.includes('Resume interrupted objective: Move Cube to X=2')));assert.equal(http.requests.at(-1).body.input.filter(i=>i.type==='function_call_output'&&i.call_id==='resume-edit').length,1);});
test('request-limit continuation retains completed tools and proposal and failed objectives enter history even without explicit resume',async t=>{const {ai,workspace,proposals,http}=await fixture(t);await ai.configure({action:'update',limits:{maxRequests:1}});let round=0;ai.fetchImpl=async(url,options)=>{http.requests.push({url,body:JSON.parse(options.body)});return new Response(JSON.stringify(response(++round===1?[tool('scene.entity.update',{entityId:workspace.project.scene.entities[0].id,name:'Already edited'},'once')]:[message('Completed the retained task.')])));};const first=await complete(ai,{text:'Rename Cube and verify'});assert.equal(first.canResume,true);assert.equal(first.steps.length,1);await ai.configure({action:'update',limits:{maxRequests:2}});const next=await complete(ai,{text:'Continue',resumeTaskId:first.id,workspaceId:first.workspaceId});assert.equal(next.status,'completed');assert.equal(next.workspaceId,first.workspaceId);assert.equal(next.steps.length,0);assert.equal(proposals.get(next.workspaceId).child.project.scene.entities[0].name,'Already edited');assert.ok(http.requests.at(-1).body.input.some(i=>i.type==='function_call_output'&&i.call_id==='once'));assert.equal(workspace.project.scene.entities[0].name,'Cube');});
test('byte length no longer spends session tokens; unknown usage stops safely and is visibly counted',async t=>{const {ai}=await fixture(t,[[message('Done')]]);await ai.configure({action:'update',limits:{maxTokens:4096}});const task=await complete(ai,{text:'Read this long objective: '+('x'.repeat(7000))});assert.equal(task.status,'completed');assert.equal(ai.status().sessionUsage.totalTokens,100);ai.fetchImpl=async()=>new Response(JSON.stringify({status:'completed',output:[message('Unreported')]}));const unknown=await complete(ai,{text:'Ask without reported usage'});assert.equal(unknown.status,'failed');assert.match(unknown.error.message,/omitted token usage/);assert.equal(ai.status().sessionUsage.unreportedRequests,1);assert.equal(ai.status().sessionUsage.totalTokens,100);});

test('resume invalidates stale acceptance and pending calls after manual proposal changes; invalid limits fail',async t=>{const {ai,workspace,proposals}=await fixture(t);await assert.rejects(ai.configure({action:'update',limits:42}),/Invalid AI limits/);await ai.configure({action:'update',limits:{maxRequests:1}});ai.fetchImpl=async()=>new Response(JSON.stringify(response([tool('scene.entity.update',{entityId:workspace.project.scene.entities[0].id,name:'Proposed'},'edit')])));const first=await complete(ai,{text:'Change then verify'});const p=proposals.get(first.workspaceId);await proposals.execute('scene.entity.update',{id:workspace.project.id,workspaceId:p.id,expectedSceneRevision:p.child.revision,entityId:workspace.project.scene.entities[0].id,name:'Manual change'},{actor:{kind:'human'}});await ai.configure({action:'update',limits:{maxRequests:4}});const resumed=ai.start({text:'Continue',resumeTaskId:first.id});ai.cancel(resumed.id);await ai.sessions.get(resumed.id).flight;assert.equal(proposals.get(first.workspaceId).child.project.scene.entities[0].name,'Manual change');assert.equal(ai.sessions.get(resumed.id).pendingCalls.length,0);assert.equal(ai.sessions.get(resumed.id).plan.steps[0].status,'todo');});

test('grouped authoring completes with three model requests, host references and actual usage detail',async t=>{
 const {ai,workspace,proposals,http}=await fixture(t),entity=workspace.project.scene.entities[0];
 const batch=(operations,id)=>({type:'function_call',name:'axiom_batch',call_id:id,arguments:JSON.stringify({operations:JSON.stringify(operations)})});
 const outputs=[[tool('entity.query',{name:'Cube'},'inspect')],[batch([{name:'scene.entity.update',arguments:{entityId:entity.id,transform:{position:[2,0,0]}}},{name:'scene.material.set',arguments:{entityId:entity.id,value:{baseColor:[0,0,1,1],metallic:0,roughness:.5,emissive:[0,0,0],alphaMode:'opaque',alphaCutoff:.5,unlit:false,castShadow:true}}},{name:'scene.primitive.create',arguments:{dimension:3,shape:'cube'}},{name:'scene.entity.update',arguments:{entityId:{$ref:'2.entityId'},name:'Floor',transform:{position:[0,-1,0],scale:[8,.2,8]}}},{name:'entity.query',arguments:{name:'Floor'}},{name:'entity.query',arguments:{entityId:entity.id}}],'author')],[message('Checked Cube X=2, blue material and Floor dimensions; no renderer measurement claimed.')]];
 ai.fetchImpl=async(url,options)=>{http.requests.push({url,body:JSON.parse(options.body)});return new Response(JSON.stringify({...response(outputs.shift()),usage:{input_tokens:100,output_tokens:20,total_tokens:120,input_tokens_details:{cached_tokens:40},output_tokens_details:{reasoning_tokens:7}}}));};
 const task=await complete(ai,{text:'Inspect Cube, move X=2, blue, create floor and verify; MAIN unchanged.'});assert.equal(task.status,'completed');assert.equal(task.requests,3);assert.equal(task.toolCalls,7,JSON.stringify(task));assert.ok(task.steps.every(s=>s.status==='completed'));const p=proposals.get(task.workspaceId);assert.equal(p.child.project.scene.entities[0].transform.position[0],2);assert.equal(p.child.project.scene.entities.find(e=>e.name==='Floor').transform.scale[0],8);assert.equal(workspace.project.scene.entities.length,1);assert.equal(workspace.project.scene.entities[0].transform.position[0],0);assert.equal(proposals.previewId,p.id);assert.equal(p.child.playing,false);assert.equal(task.requestUsage[0].cachedInputTokens,40);assert.equal(task.requestUsage[0].reasoningTokens,7);assert.equal(task.usage.totalTokens,360);assert.ok(!task.steps.some(s=>s.tool==='api.describe'));assert.ok(http.requests.at(-1).body.input.some(i=>i.type==='function_call_output'&&i.call_id==='author'));
});
