test('0.0.44 PMD has a bounded turn even with every configurable limit disabled and changing section text',async t=>{
 const {ai,proposals}=await fixture(t);await ai.configure({action:'update',limits:{maxRequests:null,maxTools:null,maxTokens:null,maxOutputTokens:null,maxSeconds:null,maxWorkTokens:null,maxStepTokens:null}});let n=0;ai.fetchImpl=async()=>{n++;return new Response(JSON.stringify(response([tool('project.master.edit',{upsertSections:[{id:'section-'+n,title:'Section '+n,parentId:null,links:[],text:'Different text '+n+' should not allow unlimited paid calls.'}]},'write-'+n)])));};
 const task=await complete(ai,{channel:'pmd',text:'Documenta este proyecto'});assert.equal(task.status,'failed');assert.equal(task.requests,16);assert.match(task.error.message,/16-request safety/);assert.equal(proposals.get(task.workspaceId).child.project.editor.pmd.sections.length,16);assert.ok(proposals.get(task.workspaceId).child.project.editor.pmd.chat.some(c=>c.role==='assistant'&&c.error));
});
test('confirmation gate presents one plan, pauses without writes, and resumes only after human approval',async t=>{
 const {ai,workspace,proposals}=await fixture(t,[[typed('work.propose',{steps:['Inspect the cube','Move it to X=2 and verify the authored transform']},'propose')],[typed('work.plan',movePlan,'plan'),typed('scene.entity.update',{entityId:'REPLACE',transform:{position:[2,0,0]}},'move')],[typed('work.check',{stepId:'move'},'check')],[message('Verified authored result')]],{testConfirmation:true});
 const first=await complete(ai,{text:'Move Cube to X=2'});assert.equal(first.status,'awaiting-approval');assert.match(first.messages[0],/1\. Inspect/);assert.equal(first.workspaceId,null);assert.equal(workspace.project.scene.entities[0].transform.position[0],0);
 const pending=ai.sessions.get(first.id);assert.equal(pending.approvalGranted,false);const http=ai.fetchImpl;ai.fetchImpl=async(...args)=>{const response=await http(...args);const data=await response.json();for(const item of data.output??[])if(item.arguments)item.arguments=item.arguments.replace('REPLACE',workspace.project.scene.entities[0].id);return new Response(JSON.stringify(data));};
 const done=await complete(ai,{text:'Sí, adelante'});assert.equal(done.status,'completed',JSON.stringify(done.error));assert.equal(done.originalObjective,'Move Cube to X=2');assert.equal(proposals.get(done.workspaceId).child.project.scene.entities[0].transform.position[0],2);assert.equal(workspace.project.scene.entities[0].transform.position[0],0);
});
