 const {ai}=await fixture(t,[[message('Read-only answer')]],{testConfirmation:true});await ai.configure({action:'confirmation',channel:'assistant',requireConfirmation:false});assert.deepEqual(ai.status().confirmations,{assistant:false,pmd:true});const answer=await complete(ai,{text:'What is this project?'});assert.equal(answer.status,'completed');assert.equal(answer.workspaceId,null);const state=JSON.parse(await readFile(ai.sessionPath,'utf8'));assert.equal(state.budgets[ai.workspace.project.id].confirmations.assistant,false);
