test('private work contracts are discoverable and absent SDK capabilities stop with a retained explanatory final response',async t=>{
 const {ai}=await fixture(t,[[tool('api.describe',{name:'work.plan'},'contract')],[tool('script.sdk.read',{query:'NavMesh.Raycast'},'missing')],[tool('script.sdk.read',{query:'NavMeshAgent.CompleteOffMeshLink'},'missing-again')],[message('Must not continue')]]);const task=await complete(ai,{text:'Inspect whether navigation is supported'});assert.equal(task.status,'failed');assert.equal(task.requests,3);assert.equal(task.steps[0].result.contractLoaded,true);assert.equal(task.error.code,'AX_AI_BLOCKED');assert.match(task.response,/NavMeshAgent/);assert.match(task.messages.at(-1),/Tarea interrumpida/);assert.equal(task.workspaceId,null);
});
